            },
            "PrinterLocked": {
              "default": false,
              "description": "The printer requires an administrator password",
              "type": "boolean"
            }
          },
          "type": "object"
        }
      },
      "type": "object"
    }
  },
  "title": "com.apple.mcxprinting",
  "type": "object"
}

